    if isNull options then nullArg "options"
    if not (isNull options.Value) && options.Value.Value <> BigInteger.Zero then invalidArg "options" "Function is not payable"
    options.To <- contract.Address
    contract.GetFunctionBySignature("0xae85314a").SendTransactionAsync(options, [| box args.Attestation; box args.Signature |])

let filterAttestationRevoked (contract: Contract) (fromBlock: BlockParameter) (toBlock: BlockParameter) =
    let filter = contract.GetEventBySignature("0x54ba2b70bc08c376f7330e9682a02493289516510eefac3f5be2843c58a29d45").CreateFilterInput(fromBlock, toBlock)
    filter

let decodeAttestationRevokedEvent (contract: Contract) (log: FilterLog) : AttestationRevokedEvent =
    let decoded = contract.GetEventBySignature("0x54ba2b70bc08c376f7330e9682a02493289516510eefac3f5be2843c58a29d45").DecodeAllEventsForEvent<AttestationRevokedEvent>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryAttestationRevoked (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<AttestationRevokedEvent>>()
        let event = contract.GetEventBySignature("0x54ba2b70bc08c376f7330e9682a02493289516510eefac3f5be2843c58a29d45")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<AttestationRevokedEvent>(decodeAttestationRevokedEvent contract log, log))
        return result
    }

