let decodeAttestationAlreadySubmittedError (data: string) : AttestationAlreadySubmittedError =
    if isNull data || not (data.StartsWith("0xfe822ec6", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<AttestationAlreadySubmittedError>).DecodeExceptionEncodedData<AttestationAlreadySubmittedError>(data)

let decodeBadSignatureError (data: string) : BadSignatureError =
    if isNull data || not (data.StartsWith("0x5cd5d233", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<BadSignatureError>).DecodeExceptionEncodedData<BadSignatureError>(data)

